static int xr_check(XrResult r, const char *what)
{
    if (XR_FAILED(r))
    {
        char str[XR_MAX_RESULT_STRING_SIZE] = "";

        if (instance)
            xrResultToString(instance, r, str);

        log_printf("OpenXR: %s failed: %d %s\n", what, (int) r, str);
        return 0;
    }
    return 1;
}

static XrPath xr_path(const char *s)
{
    XrPath p = XR_NULL_PATH;
    xrStringToPath(instance, s, &p);
    return p;
}

static void push_event(int b, int s)
{
    int next = (event_tail + 1) % MAXEVENT;

    if (next != event_head)
    {
        events[event_tail].b = b;
        events[event_tail].s = s;
        event_tail = next;
    }
}

static void push_quit(void)
{
    SDL_Event e = { SDL_QUIT };
    SDL_PushEvent(&e);
}

