/* Column-major matrix of a pose, or of its inverse. */

static void pose_matrix(float m[16], XrPosef pose, int invert)
{
    const XrQuaternionf q = pose.orientation;
    const XrVector3f    p = pose.position;
    float R[3][3];
    int r, c;

    R[0][0] = 1 - 2 * (q.y * q.y + q.z * q.z);
    R[0][1] =     2 * (q.x * q.y - q.z * q.w);
    R[0][2] =     2 * (q.x * q.z + q.y * q.w);
    R[1][0] =     2 * (q.x * q.y + q.z * q.w);
    R[1][1] = 1 - 2 * (q.x * q.x + q.z * q.z);
    R[1][2] =     2 * (q.y * q.z - q.x * q.w);
    R[2][0] =     2 * (q.x * q.z - q.y * q.w);
    R[2][1] =     2 * (q.y * q.z + q.x * q.w);
    R[2][2] = 1 - 2 * (q.x * q.x + q.y * q.y);

    for (c = 0; c < 3; c++)
    {
        for (r = 0; r < 3; r++)
            m[c * 4 + r] = invert ? R[c][r] : R[r][c];
        m[c * 4 + 3] = 0.0f;
    }
    for (r = 0; r < 3; r++)
        m[12 + r] = invert ? -(R[0][r] * p.x + R[1][r] * p.y + R[2][r] * p.z)
                           : (r == 0 ? p.x : r == 1 ? p.y : p.z);
    m[15] = 1.0f;
}

