static XrAction make_action(const char *name, XrActionType type)
{
    XrActionCreateInfo info = { XR_TYPE_ACTION_CREATE_INFO };
    XrAction action = XR_NULL_HANDLE;

    info.actionType = type;
    SDL_strlcpy(info.actionName,          name, sizeof (info.actionName));
    SDL_strlcpy(info.localizedActionName, name, sizeof (info.localizedActionName));

    xr_check(xrCreateAction(action_set, &info, &action), name);
    return action;
}

static int init_input(void)
{
    XrActionSetCreateInfo set_info = { XR_TYPE_ACTION_SET_CREATE_INFO };

    SDL_strlcpy(set_info.actionSetName,          "gameplay", sizeof (set_info.actionSetName));
    SDL_strlcpy(set_info.localizedActionSetName, "Gameplay", sizeof (set_info.localizedActionSetName));

    if (!xr_check(xrCreateActionSet(instance, &set_info, &action_set), "xrCreateActionSet"))
        return 0;

    aim_action    = make_action("aim",    XR_ACTION_TYPE_POSE_INPUT);
    select_action = make_action("select", XR_ACTION_TYPE_BOOLEAN_INPUT);
    back_action   = make_action("back",   XR_ACTION_TYPE_BOOLEAN_INPUT);
    menu_action   = make_action("menu",   XR_ACTION_TYPE_BOOLEAN_INPUT);
    stick_action  = make_action("stick",  XR_ACTION_TYPE_VECTOR2F_INPUT);
    live_action   = make_action("live",   XR_ACTION_TYPE_BOOLEAN_INPUT);
    wrist_action  = make_action("wrist",  XR_ACTION_TYPE_POSE_INPUT);
    height_action = make_action("height", XR_ACTION_TYPE_BOOLEAN_INPUT);

    {
        const XrActionSuggestedBinding bindings[] = {
            { aim_action,    xr_path("/user/hand/right/input/aim/pose")      },
            { select_action, xr_path("/user/hand/right/input/a/click")       },
            { live_action,   xr_path("/user/hand/right/input/trigger/value") },
            { wrist_action,  xr_path("/user/hand/left/input/grip/pose")      },
            { height_action, xr_path("/user/hand/left/input/x/click")        },
            { back_action,   xr_path("/user/hand/right/input/b/click")       },
            { menu_action,   xr_path("/user/hand/left/input/menu/click")     },
            { stick_action,  xr_path("/user/hand/right/input/thumbstick")    },
        };
        XrInteractionProfileSuggestedBinding suggested = {
            XR_TYPE_INTERACTION_PROFILE_SUGGESTED_BINDING
        };

        suggested.interactionProfile     = xr_path("/interaction_profiles/oculus/touch_controller");
        suggested.countSuggestedBindings = sizeof (bindings) / sizeof (bindings[0]);
        suggested.suggestedBindings      = bindings;

        if (!xr_check(xrSuggestInteractionProfileBindings(instance, &suggested),
                      "xrSuggestInteractionProfileBindings"))
            return 0;
    }

    {
        XrActionSpaceCreateInfo info = { XR_TYPE_ACTION_SPACE_CREATE_INFO };

        info.action = aim_action;
        info.poseInActionSpace.orientation.w = 1.0f;

        if (!xr_check(xrCreateActionSpace(session, &info, &aim_space), "xrCreateActionSpace"))
            return 0;

        info.action = wrist_action;

        if (!xr_check(xrCreateActionSpace(session, &info, &wrist_space), "xrCreateActionSpace"))
            return 0;
    }

    {
        XrSessionActionSetsAttachInfo info = { XR_TYPE_SESSION_ACTION_SETS_ATTACH_INFO };

        info.countActionSets = 1;
        info.actionSets      = &action_set;

        return xr_check(xrAttachSessionActionSets(session, &info), "xrAttachSessionActionSets");
    }
}

static int get_bool(XrAction action)
{
    XrActionStateGetInfo info = { XR_TYPE_ACTION_STATE_GET_INFO };
    XrActionStateBoolean state = { XR_TYPE_ACTION_STATE_BOOLEAN };

    info.action = action;
    xrGetActionStateBoolean(session, &info, &state);
    return state.isActive && state.currentState;
}

static void track_button(XrAction action, int button, int *prev)
{
    int curr = get_bool(action);

    if (curr != *prev)
        push_event(button, curr);

    *prev = curr;
}

static void track_stick_axis(float v, int neg, int pos, int *prev)
{
    /* -1, 0, +1 with hysteresis, reported as D-pad presses. */

    int curr = (v < -0.6f) ? -1 : (v > 0.6f) ? +1 : (fabsf(v) < 0.4f) ? 0 : *prev;

    if (curr != *prev)
    {
        if (*prev < 0) push_event(neg, 0);
        if (*prev > 0) push_event(pos, 0);
        if (curr  < 0) push_event(neg, 1);
        if (curr  > 0) push_event(pos, 1);
    }
    *prev = curr;
}

static void step_input(void)
{
    static int select_prev, back_prev, menu_prev, x_prev, y_prev;

    XrActiveActionSet active = { action_set, XR_NULL_PATH };
    XrActionsSyncInfo sync = { XR_TYPE_ACTIONS_SYNC_INFO };

    sync.countActiveActionSets = 1;
    sync.activeActionSets      = &active;

    if (!focused || xrSyncActions(session, &sync) != XR_SUCCESS)
    {
        tilt_ok = 0;
        hand_ok = 0;
        return;
    }

    hand_live = get_bool(live_action);

    {
        XrSpaceLocation loc = { XR_TYPE_SPACE_LOCATION };
        const XrSpaceLocationFlags valid = XR_SPACE_LOCATION_POSITION_VALID_BIT |
                                           XR_SPACE_LOCATION_ORIENTATION_VALID_BIT;

        xrLocateSpace(wrist_space, space, frame.predictedDisplayTime, &loc);

        if ((wrist_ok = (loc.locationFlags & valid) == valid))
            pose_matrix(wrist_G, loc.pose, 0);
    }

    track_button(select_action, config_get_d(CONFIG_JOYSTICK_BUTTON_A),     &select_prev);
    track_button(back_action,   config_get_d(CONFIG_JOYSTICK_BUTTON_B),     &back_prev);
    track_button(menu_action,   config_get_d(CONFIG_JOYSTICK_BUTTON_START), &menu_prev);

    {
        XrActionStateGetInfo info = { XR_TYPE_ACTION_STATE_GET_INFO };
        XrActionStateVector2f stick = { XR_TYPE_ACTION_STATE_VECTOR2F };

        info.action = stick_action;
        xrGetActionStateVector2f(session, &info, &stick);

        track_stick_axis(+stick.currentState.x,
                         config_get_d(CONFIG_JOYSTICK_DPAD_L),
                         config_get_d(CONFIG_JOYSTICK_DPAD_R), &x_prev);
        track_stick_axis(-stick.currentState.y,
                         config_get_d(CONFIG_JOYSTICK_DPAD_U),
                         config_get_d(CONFIG_JOYSTICK_DPAD_D), &y_prev);
    }

    /* Hand tilt: hold the controller like a tray. */

    {
        XrSpaceVelocity vel = { XR_TYPE_SPACE_VELOCITY };
        XrSpaceLocation loc = { XR_TYPE_SPACE_LOCATION, &vel };
        const XrSpaceLocationFlags valid = XR_SPACE_LOCATION_POSITION_VALID_BIT |
                                           XR_SPACE_LOCATION_ORIENTATION_VALID_BIT;

        xrLocateSpace(aim_space, space, frame.predictedDisplayTime, &loc);

        if ((hand_ok = (loc.locationFlags & valid) == valid))
        {
            pose_matrix(hand_G, loc.pose, 0);

            hand_v[0] = vel.linearVelocity.x;
            hand_v[1] = vel.linearVelocity.y;
            hand_v[2] = vel.linearVelocity.z;
            hand_w[0] = vel.angularVelocity.x;
            hand_w[1] = vel.angularVelocity.y;
            hand_w[2] = vel.angularVelocity.z;

            if (!(vel.velocityFlags & XR_SPACE_VELOCITY_LINEAR_VALID_BIT))
                hand_v[0] = hand_v[1] = hand_v[2] = 0.0f;
            if (!(vel.velocityFlags & XR_SPACE_VELOCITY_ANGULAR_VALID_BIT))
                hand_w[0] = hand_w[1] = hand_w[2] = 0.0f;
        }

        /* Course height: press X with the play hand where the ground goes. */

        {
            static int height_prev;
            int height = get_bool(height_action);

            if (height && !height_prev && hand_ok && floored)
            {
                course_h = SDL_clamp(hand_G[13], 0.0f, 1.5f);
                config_set_d(CONFIG_COURSE_HEIGHT, (int) (course_h * 100.0f));
                config_save();
                log_printf("Course height %.2f m\n", course_h);
            }
            height_prev = height;
        }

        if (loc.locationFlags & XR_SPACE_LOCATION_ORIENTATION_VALID_BIT)
        {
            const XrQuaternionf q = loc.pose.orientation;

            /*
             * The floor copies the tilt of the controller's up axis. With
             * the floor rotated by Rz(-z) Rx(-x), its normal is
             * (cos x sin z, cos x cos z, -sin x).
             */

            float nx =     2 * (q.x * q.y - q.z * q.w);
            float ny = 1 - 2 * (q.x * q.x + q.z * q.z);
            float nz =     2 * (q.y * q.z + q.x * q.w);

            tilt_x = -V_DEG(asinf(nz));
            tilt_z =  V_DEG(atan2f(nx, ny));
            tilt_ok = 1;
        }
        else tilt_ok = 0;
    }

    /* Testing without controllers: `adb shell setprop debug.neverball.tilt "x z"`. */

    {
        char value[PROP_VALUE_MAX];

        if (__system_property_get("debug.neverball.tilt", value) > 0 &&
            sscanf(value, "%f %f", &tilt_x, &tilt_z) == 2)
            tilt_ok = 1;
    }
}

