static int init_swapchains(void)
{
    /*
     * gl4es renames textures, so attaching the runtime's texture names
     * through it would attach a fresh texture of its own. Framebuffer
     * names are real, so bind through gl4es and attach with GLES itself.
     */
    void (*gles_framebuffer_texture_2d)(GLenum, GLenum, GLenum, GLuint, GLint);
    void *gles = dlopen("libGLESv2.so", RTLD_NOW | RTLD_LOCAL);

    int64_t formats[128];
    uint32_t n = 0, i, j;
    int64_t format = 0;

    if (!gles || !(gles_framebuffer_texture_2d = dlsym(gles, "glFramebufferTexture2D")))
    {
        log_printf("OpenXR: no GLES glFramebufferTexture2D: %s\n", dlerror());
        return 0;
    }

    for (i = 0; i < 2; i++)
    {
        config_views[i].type = XR_TYPE_VIEW_CONFIGURATION_VIEW;
        config_views[i].next = NULL;
    }

    if (!xr_check(xrEnumerateViewConfigurationViews(instance, system_id,
                  XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO, 2, &n, config_views),
                  "xrEnumerateViewConfigurationViews"))
        return 0;

    if (!xr_check(xrEnumerateSwapchainFormats(session, 0, &n, NULL),
                  "xrEnumerateSwapchainFormats") ||
        !xr_check(xrEnumerateSwapchainFormats(session, SDL_min(n, 128), &n, formats),
                  "xrEnumerateSwapchainFormats"))
        return 0;

    for (i = 0; i < n; i++)
        if (formats[i] == XR_GL_SRGB8_ALPHA8)
            format = formats[i];
    if (!format)
        format = n ? formats[0] : XR_GL_RGBA8;

    for (i = 0; i < 2; i++)
    {
        XrSwapchainCreateInfo info = { XR_TYPE_SWAPCHAIN_CREATE_INFO };
        XrSwapchainImageOpenGLESKHR images[MAXIMG];
        const int w = config_views[i].recommendedImageRectWidth;
        const int h = config_views[i].recommendedImageRectHeight;

        info.usageFlags  = XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT |
                           XR_SWAPCHAIN_USAGE_SAMPLED_BIT;
        info.format      = format;
        info.sampleCount = 1;
        info.width       = w;
        info.height      = h;
        info.faceCount   = 1;
        info.arraySize   = 1;
        info.mipCount    = 1;

        if (!xr_check(xrCreateSwapchain(session, &info, &swapchain[i]), "xrCreateSwapchain"))
            return 0;

        for (j = 0; j < MAXIMG; j++)
        {
            images[j].type = XR_TYPE_SWAPCHAIN_IMAGE_OPENGL_ES_KHR;
            images[j].next = NULL;
        }

        if (!xr_check(xrEnumerateSwapchainImages(swapchain[i], MAXIMG, &image_count[i],
                      (XrSwapchainImageBaseHeader *) images), "xrEnumerateSwapchainImages"))
            return 0;

        glGenRenderbuffers(1, &depth[i]);
        glBindRenderbuffer(GL_RENDERBUFFER, depth[i]);
        glRenderbufferStorage(GL_RENDERBUFFER, GL_DEPTH24_STENCIL8, w, h);

        glGenFramebuffers_(image_count[i], framebuffer[i]);

        for (j = 0; j < image_count[i]; j++)
        {
            glBindFramebuffer_(GL_FRAMEBUFFER, framebuffer[i][j]);
            gles_framebuffer_texture_2d(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0,
                                        GL_TEXTURE_2D, images[j].image, 0);
            glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT,
                                      GL_RENDERBUFFER, depth[i]);
            glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_STENCIL_ATTACHMENT,
                                      GL_RENDERBUFFER, depth[i]);

            if (glCheckFramebufferStatus_(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE)
                log_printf("OpenXR: eye %u framebuffer %u incomplete\n", i, j);
        }
        glBindFramebuffer_(GL_FRAMEBUFFER, 0);

        layer_views[i].type = XR_TYPE_COMPOSITION_LAYER_PROJECTION_VIEW;
        layer_views[i].subImage.swapchain = swapchain[i];
        layer_views[i].subImage.imageRect.extent.width  = w;
        layer_views[i].subImage.imageRect.extent.height = h;

        views[i].type = XR_TYPE_VIEW;
    }

    log_printf("OpenXR: %dx%d per eye, format 0x%llx\n",
               config_views[0].recommendedImageRectWidth,
               config_views[0].recommendedImageRectHeight, (long long) format);
    return 1;
}

static int init_session(void)
{
    PFN_xrGetOpenGLESGraphicsRequirementsKHR get_requirements = NULL;
    XrGraphicsRequirementsOpenGLESKHR requirements = {
        XR_TYPE_GRAPHICS_REQUIREMENTS_OPENGL_ES_KHR
    };
    XrGraphicsBindingOpenGLESAndroidKHR binding = {
        XR_TYPE_GRAPHICS_BINDING_OPENGL_ES_ANDROID_KHR
    };
    XrSessionCreateInfo info = { XR_TYPE_SESSION_CREATE_INFO };
    XrReferenceSpaceCreateInfo space_info = { XR_TYPE_REFERENCE_SPACE_CREATE_INFO };
    EGLint config_id = 0, n = 0;
    EGLint attribs[] = { EGL_CONFIG_ID, 0, EGL_NONE };

    xrGetInstanceProcAddr(instance, "xrGetOpenGLESGraphicsRequirementsKHR",
                          (PFN_xrVoidFunction *) &get_requirements);

    if (!get_requirements ||
        !xr_check(get_requirements(instance, system_id, &requirements),
                  "xrGetOpenGLESGraphicsRequirementsKHR"))
        return 0;

    binding.display = eglGetCurrentDisplay();
    binding.context = eglGetCurrentContext();

    eglQueryContext(binding.display, binding.context, EGL_CONFIG_ID, &config_id);
    attribs[1] = config_id;
    eglChooseConfig(binding.display, attribs, &binding.config, 1, &n);

    info.next     = &binding;
    info.systemId = system_id;

    if (!xr_check(xrCreateSession(instance, &info, &session), "xrCreateSession"))
        return 0;

    space_info.referenceSpaceType = XR_REFERENCE_SPACE_TYPE_LOCAL;
    space_info.poseInReferenceSpace.orientation.w = 1.0f;

    if (!xr_check(xrCreateReferenceSpace(session, &space_info, &local),
                  "xrCreateReferenceSpace"))
        return 0;

    /* Render in the floor-level stage space if there is one. */

    space_info.referenceSpaceType = XR_REFERENCE_SPACE_TYPE_STAGE;

    floored = XR_SUCCEEDED(xrCreateReferenceSpace(session, &space_info, &space));

    if (!floored)
        space = local;

    m_ident(L);

    course_h = config_get_d(CONFIG_COURSE_HEIGHT) / 100.0f;

    return init_swapchains() && init_input();
}

static int init_instance(void)
{
    JNIEnv *env = (JNIEnv *) SDL_AndroidGetJNIEnv();
    jobject activity = (jobject) SDL_AndroidGetActivity();
    JavaVM *vm = NULL;

    PFN_xrInitializeLoaderKHR init_loader = NULL;
    XrLoaderInitInfoAndroidKHR loader_info = { XR_TYPE_LOADER_INIT_INFO_ANDROID_KHR };
    XrInstanceCreateInfoAndroidKHR android_info = { XR_TYPE_INSTANCE_CREATE_INFO_ANDROID_KHR };
    XrInstanceCreateInfo info = { XR_TYPE_INSTANCE_CREATE_INFO };
    XrSystemGetInfo system_info = { XR_TYPE_SYSTEM_GET_INFO };

    const char *extensions[] = {
        XR_KHR_ANDROID_CREATE_INSTANCE_EXTENSION_NAME,
        XR_KHR_OPENGL_ES_ENABLE_EXTENSION_NAME,
    };

    (*env)->GetJavaVM(env, &vm);
    activity = (*env)->NewGlobalRef(env, activity);

    xrGetInstanceProcAddr(XR_NULL_HANDLE, "xrInitializeLoaderKHR",
                          (PFN_xrVoidFunction *) &init_loader);

    loader_info.applicationVM      = vm;
    loader_info.applicationContext = activity;

    if (!init_loader ||
        !xr_check(init_loader((const XrLoaderInitInfoBaseHeaderKHR *) &loader_info),
                  "xrInitializeLoaderKHR"))
        return 0;

    android_info.applicationVM       = vm;
    android_info.applicationActivity = activity;

    info.next = &android_info;
    info.enabledExtensionCount = 2;
    info.enabledExtensionNames = extensions;
    info.applicationInfo.apiVersion = XR_API_VERSION_1_0;
    info.applicationInfo.applicationVersion = 1;
    SDL_strlcpy(info.applicationInfo.applicationName, "Neverball",
                sizeof (info.applicationInfo.applicationName));

    if (!xr_check(xrCreateInstance(&info, &instance), "xrCreateInstance"))
        return 0;

    system_info.formFactor = XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY;

    return xr_check(xrGetSystem(instance, &system_info, &system_id), "xrGetSystem");
}

