void tilt_init(void)
{
}

void tilt_free(void)
{
}

int tilt_stat(void)
{
    return running && tilt_ok;
}

int tilt_get_button(int *b, int *s)
{
    if (event_head == event_tail)
        return 0;

    *b = events[event_head].b;
    *s = events[event_head].s;
    event_head = (event_head + 1) % MAXEVENT;
    return 1;
}

float tilt_get_x(void)
{
    return tilt_x;
}

float tilt_get_z(void)
{
    return tilt_z;
}

